// Labelled Chord Diagram — Network, route: jsx
// Source: chord-diagram_2
//
// Self-contained: every local import is inlined below. Requires only d3, react.
// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

import { useMemo } from 'react';
import * as d3 from 'd3';

/** Illustrative pairing matrix: row is one partner's hair colour, column the other's. */
const hairColours = ['black', 'blond', 'brown', 'red'];
/** The Circos palette this example borrows, with pure black lifted so it reads on a dark panel. */
const colors = ['#6f6862', '#ffdd89', '#957244', '#f26223'];

const pairings = [
  [11975, 5871, 8916, 2868],
  [1951, 10048, 2060, 6171],
  [8010, 16145, 8090, 8045],
  [1013, 990, 940, 6907]
];

/** A square pairing matrix and the name of each of its groups. */
export type Data = { names: string[]; matrix: number[][] };

const DEMO: Data = { names: hairColours, matrix: pairings };

const MAX_SIZE = 560;
/** Room outside the ring for the ruler, its labels and the group names. */
const MARGIN = 84;
const RING_THICKNESS = 16;
const MINOR_TICK = 4;
const MAJOR_TICK = 9;
const NAME_OFFSET = 46;
const MIN_SIZE_FOR_RULER = 300;

const formatCount = d3.format(',');

/** Circos ruler: a graduation every ~1/100 of the total, a labelled major every ~1/20. */
function rulerOf(matrix: number[][]) {
  const total = d3.sum(matrix, (row) => d3.sum(row));
  const minorStep = d3.tickStep(0, total, 100);
  return {
    total,
    minorStep,
    majorStep: d3.tickStep(0, total, 20),
    // formatPrefix pins every label to one unit, so the whole ring reads as a single scale.
    formatTick: d3.formatPrefix(',.0', minorStep)
  };
}

type GroupTick = { value: number; angle: number; isMajor: boolean };

function groupTicks(group: d3.ChordGroup, minorStep: number, majorStep: number): GroupTick[] {
  const k = (group.endAngle - group.startAngle) / group.value;
  return d3.range(0, group.value, minorStep).map((value) => ({
    value,
    angle: value * k + group.startAngle,
    isMajor: value % majorStep === 0
  }));
}

function describe(chord: d3.Chord, names: string[]): string {
  const source = names[chord.source.index];
  const target = names[chord.target.index];
  if (chord.source.index === chord.target.index) {
    return `${formatCount(chord.source.value)} ${source} with ${target}`;
  }
  return [
    `${formatCount(chord.source.value)} ${source} → ${target}`,
    `${formatCount(chord.target.value)} ${target} → ${source}`
  ].join('\n');
}

export default function ChordDiagramLabelled({
  data = DEMO,
  width
}: {
  data?: Data;
  width: number;
}) {
  const { names, matrix } = data;
  const { total, minorStep, majorStep, formatTick } = useMemo(() => rulerOf(matrix), [matrix]);
  const height = Math.min(width, MAX_SIZE);
  const size = Math.min(width, height);
  const showRuler = size >= MIN_SIZE_FOR_RULER;
  const outerRadius = Math.max(size / 2 - (showRuler ? MARGIN : 24), 40);
  const innerRadius = outerRadius - RING_THICKNESS;

  const chords = useMemo(
    () => d3.chord().padAngle(20 / innerRadius).sortSubgroups(d3.descending)(matrix),
    [matrix, innerRadius]
  );

  const arc = useMemo(
    () => d3.arc<d3.ChordGroup>().innerRadius(innerRadius).outerRadius(outerRadius),
    [innerRadius, outerRadius]
  );

  // @types/d3-chord declares a void-returning overload first, so the path-string
  // signature has to be pinned by the annotation.
  const ribbon = useMemo<(chord: d3.Chord) => string | null>(
    () => d3.ribbon<d3.Chord, d3.ChordSubgroup>().radius(innerRadius),
    [innerRadius]
  );

  if (width === 0) return null;

  return (
    <svg
      viewBox={`${-width / 2} ${-height / 2} ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label={`Chord diagram of hair colour pairings, each arc graduated with a Circos-style ruler labelled every ${formatTick(
        majorStep
      )} out of ${formatCount(total)} pairings. Illustrative sample data, not a real survey.`}
    >
      {chords.groups.map((group) => {
        const name = names[group.index];
        const midAngle = (group.startAngle + group.endAngle) / 2;
        const isLeftHalf = midAngle > Math.PI;
        return (
          <g key={name}>
            <path d={arc(group) ?? undefined} fill={colors[group.index]}>
              <title>{`${name}\n${formatCount(group.value)} pairings`}</title>
            </path>

            {showRuler && (
              <g fontSize={9} fill="var(--muted)">
                {groupTicks(group, minorStep, majorStep).map((tick) => (
                  <g
                    key={tick.value}
                    transform={`rotate(${(tick.angle * 180) / Math.PI - 90}) translate(${outerRadius},0)`}
                  >
                    <line
                      x2={tick.isMajor ? MAJOR_TICK : MINOR_TICK}
                      stroke={tick.isMajor ? 'var(--text)' : 'var(--muted)'}
                    />
                    {/* Zero repeats once per group and only restates the arc boundary. */}
                    {tick.isMajor && tick.value > 0 && (
                      <text
                        x={MAJOR_TICK + 3}
                        dy="0.35em"
                        transform={tick.angle > Math.PI ? 'rotate(180) translate(-24)' : undefined}
                        textAnchor={tick.angle > Math.PI ? 'end' : undefined}
                      >
                        {formatTick(tick.value)}
                      </text>
                    )}
                  </g>
                ))}
              </g>
            )}

            {showRuler && (
              <g
                fontSize={12}
                fontWeight="bold"
                fill="var(--text)"
                transform={`rotate(${(midAngle * 180) / Math.PI - 90}) translate(${outerRadius + NAME_OFFSET},0)`}
              >
                <text
                  dy="0.35em"
                  transform={isLeftHalf ? 'rotate(180)' : undefined}
                  textAnchor={isLeftHalf ? 'end' : undefined}
                >
                  {name}
                </text>
              </g>
            )}
          </g>
        );
      })}

      {/* Ribbons are coloured by their target so each bundle reads as arriving, not leaving. */}
      <g fillOpacity={0.7}>
        {chords.map((chord) => (
          <path
            key={`${chord.source.index}-${chord.target.index}`}
            d={ribbon(chord) ?? undefined}
            fill={colors[chord.target.index]}
            stroke="var(--bg)"
            strokeWidth={0.5}
          >
            <title>{describe(chord, names)}</title>
          </path>
        ))}
      </g>

      {showRuler && (
        <text
          x={0}
          y={height / 2 - 8}
          textAnchor="middle"
          fontSize={10}
          fill="var(--muted)"
        >
          Illustrative sample matrix from the D3 chord example, not a real survey.
        </text>
      )}
    </svg>
  );
}
